pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner, address fakeCaller) public {
        vm.assume(newOwner != address(0));
        vm.assume(fakeCaller != address(0));
        vm.startPrank(fakeCaller);
        bool ok = false;
        try c.transferOwnership(newOwner) { ok = true; } catch { }
        vm.stopPrank();
        address currentOwner = c.owner();
        if (ok) {
            assertTrue(currentOwner == newOwner);
        } else {
            assertTrue(currentOwner == address(this));
        }
    }
}

