pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(newOwner != caller);
        // Transfer ownership to newOwner (caller must be current owner, which is address(this))
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // Read owner from a different address
        vm.prank(caller);
        address returnedOwner = c.owner();
        // The reference always returns newOwner; the mutant returns caller
        assertTrue(returnedOwner == newOwner);
    }
}

