pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this) && caller != address(0));
        address directOwner = c.owner();
        vm.prank(caller);
        address staticOwner;
        bool ok;
        (ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        if (ok) {
            staticOwner = abi.decode(data, (address));
        }
        assertTrue(ok && directOwner == staticOwner);
    }
}

