pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // 1. The fuzzer supplies any address as the candidate new owner.
        // 2. No adversarial helper is needed; the bug is a missing require inside transferOwnership.
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // 3. The invariant: after any valid transferOwnership call, the owner must never be the zero address.
        assertTrue(c.owner() != address(0));
    }
}

